import tabulate

def test_call(data, maxcolwidths=None):
    try:
        if maxcolwidths is None:
            res = tabulate.tabulate(data)
        else:
            res = tabulate.tabulate(data, maxcolwidths=maxcolwidths)
    except Exception as e:
        print(f'Exception: {e}')
        raise
    print(f'Result: {repr(res)}')
    assert res == ''

test_call([])
test_call([], maxcolwidths=5)

import click
from click.exceptions import MissingParameter

@click.command()
@click.option('--switch', type=bool)
def f(switch):
    print(switch)

if __name__ == '__main__':
    opt = f.params[0]
    print(f'is_flag={opt.is_flag}')
    print(f'is_bool_flag={opt.is_bool_flag}')
    try:
        f(['--switch'])
    except MissingParameter as e:
        print(f'Exception: {e}')
        raise
